:root {
  --bg: #f5f5f7;
  --surface: #ffffff;
  --surface-2: #fbfbfd;
  --text: #1d1d1f;
  --muted: #6e6e73;
  --accent: #0066cc;
  --border: #d2d2d7;
  --radius: 20px;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "SF Pro Text", "SF Pro Display", "Helvetica Neue", Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(1200px, 92vw); margin: 0 auto; }
.top-nav {
  position: sticky; top: 0; z-index: 40;
  backdrop-filter: blur(18px);
  background: rgba(245,245,247,0.88);
  border-bottom: 1px solid rgba(210,210,215,0.6);
}
.top-nav-inner {
  height: 48px; display: flex; align-items: center; gap: 20px;
  font-size: 14px; color: #3a3a3c;
}
.brand { font-weight: 600; letter-spacing: 0.2px; }
.top-links { display: flex; gap: 18px; overflow-x: auto; white-space: nowrap; }
.hero {
  padding: 72px 0 44px;
  text-align: center;
}
.hero h1 {
  margin: 0;
  font-size: clamp(2.2rem, 6vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}
.hero p {
  margin: 14px auto 0;
  max-width: 760px;
  color: var(--muted);
  font-size: clamp(1rem, 2vw, 1.35rem);
  line-height: 1.35;
}
.section { padding: 24px 0 32px; }
.section h2 {
  font-size: clamp(1.8rem, 4.2vw, 2.8rem);
  letter-spacing: -0.02em;
  margin: 0 0 18px;
}
.subtitle { color: var(--muted); margin: -8px 0 18px; }
.product-strip {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  padding: 2px 4px 8px;
  scrollbar-width: none;
}
.product-strip::-webkit-scrollbar { display: none; }
.strip-item {
  min-width: 110px;
  text-align: center;
  color: #444;
  font-size: 13px;
}
.icon-box {
  width: 88px; height: 62px;
  margin: 0 auto 10px;
  border-radius: 14px;
  background: linear-gradient(145deg,#ececef,#f8f8fa);
  display: grid; place-items: center;
  font-size: 28px;
}
.carousel-wrap { position: relative; }
.carousel {
  display: flex;
  gap: 18px;
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: 4px 2px 10px;
  scrollbar-width: none;
}
.carousel::-webkit-scrollbar { display: none; }
.card {
  flex: 0 0 320px;
  border-radius: var(--radius);
  background: var(--surface);
  padding: 20px;
  min-height: 360px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 4px 18px rgba(0,0,0,0.05);
}
.card.large { flex-basis: 420px; min-height: 460px; }
.card-media {
  border-radius: 16px;
  height: 180px;
  background: linear-gradient(145deg, #eef2ff, #f8fbff);
  margin-bottom: 16px;
  display: grid; place-items: center;
  font-size: 56px;
}
.card h3 { margin: 0; font-size: 1.45rem; letter-spacing: -0.01em; }
.card p { margin: 8px 0 0; color: var(--muted); line-height: 1.35; }
.price { margin-top: 12px; font-size: 1rem; color: #2b2b2d; }
.financing { margin-top: 4px; color: var(--muted); font-size: 0.92rem; }
.cta-row { margin-top: 14px; display: flex; gap: 14px; font-size: 0.95rem; }
.cta-row a { color: var(--accent); font-weight: 500; }
.carousel-nav {
  position: absolute;
  top: -58px;
  right: 0;
  display: flex;
  gap: 10px;
}
.nav-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: rgba(255,255,255,0.95);
  color: #333;
  cursor: pointer;
  font-size: 18px;
}
.grid-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 16px;
}
.tile {
  border-radius: 24px;
  min-height: 420px;
  background: var(--surface);
  padding: 28px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.tile-media {
  height: 190px;
  border-radius: 16px;
  background: linear-gradient(135deg, #edf2ff 0%, #f8f8fa 100%);
  display: grid;
  place-items: center;
  font-size: 70px;
}
.tile h3 { margin: 0; font-size: 2rem; letter-spacing: -0.02em; }
.tile p { margin: 8px 0 0; color: var(--muted); }
.tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 10px 0 16px;
}
.tab-btn {
  border: 1px solid var(--border);
  padding: 10px 14px;
  border-radius: 999px;
  background: #fff;
  font-weight: 500;
  cursor: pointer;
}
.tab-btn.active {
  background: #1d1d1f;
  color: #fff;
  border-color: #1d1d1f;
}
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.quick-links { display: flex; gap: 10px; flex-wrap: wrap; }
.pill {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 16px;
  background: #fff;
  font-size: 14px;
  color: #222;
}
.sticky-sections {
  position: sticky;
  top: 48px;
  z-index: 30;
  background: rgba(245,245,247,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.section-nav {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  white-space: nowrap;
  padding: 10px 0;
}
.section-nav a {
  font-size: 14px;
  color: #3a3a3c;
  padding: 6px 10px;
  border-radius: 999px;
}
.section-nav a:hover { background: #fff; }
.footer {
  margin-top: 38px;
  border-top: 1px solid var(--border);
  background: #f0f0f2;
  padding: 20px 0 36px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0,1fr));
  gap: 18px;
}
.footer-col h4 {
  margin: 8px 0;
  font-size: 14px;
}
.footer-col a {
  display: block;
  color: #525256;
  font-size: 13px;
  margin: 7px 0;
}
.footer-toggle { display: none; }
@media (max-width: 900px) {
  .grid-tiles { grid-template-columns: 1fr; }
  .card.large { flex-basis: 360px; }
}
@media (max-width: 760px) {
  .footer-grid { display: block; }
  .footer-col {
    border-top: 1px solid #d9d9de;
    padding: 6px 0;
  }
  .footer-col h4 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    margin: 8px 0;
  }
  .footer-col .links { display: none; padding-bottom: 8px; }
  .footer-col.open .links { display: block; }
  .footer-toggle { display: inline; color: #7a7a7f; }
}
EOF

